CustomField.formula:
if ( 

(not(isblank(End_Date__c)) && 

(ispickval(Job_Type__c, "Temporary") || ispickval(Job_Type__c, "Internship"))

),

text(Send_Out_Date__c) & " | " & Organization_Summary__c & " - " & Job_Title__c & " | Assignment Complete",

text(Send_Out_Date__c) & " | " & Organization_Summary__c & " - " & Job_Title__c & " | Staff: " & CAM__c

)
